    if (value && range)
      {
        if (range->lower)
          if (auto lower = convert (kind, *range->lower); !lower || *value < *lower)
            return std::nullopt;
        if (range->upper)
          if (auto upper = convert (kind, *range->upper); !upper || *value > *upper)
            return std::nullopt;
      }
    if (value && predicate && !predicate (*value))
      return std::nullopt;
    return value;
